import hashlib
import base64

expected_a = base64.b64decode("XyRVNXb7wf4Hf+oG4Dx+RTKIM/cqgoTcfimlIbxQXcY=")
expected_b = base64.b64decode("WcAQF0dqPIH9UiFgF1hCqATqqcjoVi/WN5neFwiuUts=")

content_b = b"SELECT 2;\n"

# brute force with various approaches for b.sql
# First let me brute force the format
for include_a_hash in [True, False]:
    for prefix_format in [None, "h1:", "", "atlas:"]:
        for separator in [None, ":", "\n", " ", ""]:
            for name_format in ["b.sql", "b", "hash_test3/b.sql", "/tmp/hash_test3/b.sql"]:
                parts = []
                if include_a_hash:
                    if prefix_format:
                        parts.append(prefix_format.encode() + base64.b64encode(expected_a))
                    else:
                        parts.append(expected_a)
                if separator:
                    parts.append(separator.encode())
                parts.append(name_format.encode())
                parts.append(content_b)
                data = b"".join(parts)
                h = hashlib.sha256(data).digest()
                if h == expected_b:
                    print(f"FOUND! include_a={include_a_hash}, prefix={prefix_format!r}, sep={separator!r}, name={name_format!r}")
                    print(f"Data: {data!r}")
print("Done brute force")
EOF

