python3 << 'EOF'
import hashlib
import base64

# So dir = SHA256(last_filename + b64(last_cumulative_hash)) works for single files
# But not for multiple files (in the ab case it doesn't work with last_filename)

# Let me try all combinations for the ab case
content_a = b"SELECT 1;\n"
content_b = b"SELECT 2;\n"

h_a = hashlib.sha256(b"a.sql" + content_a).digest()
h_b_cum = hashlib.sha256(b"a.sql" + content_a + b"b.sql" + content_b).digest()

dir_ab = base64.b64decode("HNvw2apPKcmALnRJUoGAIQ3lBYZmXQHfmcOJBMHGQ5M=")

# Try all filename + hash combinations
for name in [b"a.sql", b"b.sql", b""]:
    for h in [h_a, h_b_cum]:
        for use_b64 in [True, False]:
            if use_b64:
                h_data = base64.b64encode(h)
            else:
                h_data = h
            data = name + h_data
            result = hashlib.sha256(data).digest()
            if result == dir_ab:
                print(f"MATCH! name={name!r}, hash={'b64(h_b_cum)' if (h == h_b_cum and use_b64) else str((h==h_a, use_b64))}")

# Try: SHA256(h_a + b64(h_b_cum))?
for h1, h2 in [(h_a, h_b_cum), (h_b_cum, h_a)]:
    for use_b64 in [True, False]:
        if use_b64:
            h2_data = base64.b64encode(h2)
        else:
            h2_data = h2
        for use_b64_1 in [True, False]:
            if use_b64_1:
                h1_data = base64.b64encode(h1)
            else:
                h1_data = h1
            data = h1_data + h2_data
            result = hashlib.sha256(data).digest()
            if result == dir_ab:
                print(f"MATCH! h1_b64={use_b64_1}, h2_b64={use_b64}")

print("Done")
EOF

