"""HCL canonical formatter."""
import re


def format_hcl(content):
    """Format HCL content to canonical layout."""
    try:
        formatter = HCLFormatter(content)
        return formatter.format()
    except Exception:
        return content


class HCLFormatter:
    def __init__(self, content):
        self.content = content

    def format(self):
        tokens = self._lex(self.content)
        result = self._format_tokens(tokens, 0)
        if result and not result.endswith('\n'):
            result += '\n'
        return result

    def _lex(self, content):
        """Lex HCL into tokens."""
        lines = content.split('\n')
        if lines and lines[-1] == '':
            lines = lines[:-1]

        nodes = []
        i = 0
        while i < len(lines):
            line = lines[i]
            stripped = line.strip()

            if not stripped:
                nodes.append({'type': 'blank'})
                i += 1
            elif stripped.startswith('#') or stripped.startswith('//'):
                nodes.append({'type': 'comment', 'text': stripped})
                i += 1
            elif stripped == '}':
                nodes.append({'type': 'close'})
                i += 1
            elif stripped.endswith('{'):
                header = self._normalize_header(stripped[:-1].rstrip())
                block = {'type': 'block', 'header': header, 'children': []}
                nodes.append(block)
                i += 1
                # Collect children until matching }
                depth = 1
                while i < len(lines) and depth > 0:
                    l = lines[i]
                    s = l.strip()
                    if not s:
                        block['children'].append({'type': 'blank'})
                    elif s.startswith('#') or s.startswith('//'):
                        block['children'].append({'type': 'comment', 'text': s})
                    elif s == '}':
                        depth -= 1
                        if depth == 0:
                            i += 1
                            break
                        else:
                            block['children'].append({'type': 'close'})
                    elif s.endswith('{'):
                        # Nested block - collect it recursively
                        inner_lines = [l]
                        inner_depth = 1
                        i += 1
                        while i < len(lines) and inner_depth > 0:
                            il = lines[i]
                            is_ = il.strip()
                            inner_lines.append(il)
                            if is_.endswith('{') and not is_.startswith('#'):
                                inner_depth += 1
                            elif is_ == '}':
                                inner_depth -= 1
                            i += 1
                        # Parse the inner block
                        inner_content = '\n'.join(inner_lines)
                        inner_nodes = self._lex(inner_content)
                        if inner_nodes:
                            block['children'].append(inner_nodes[0])
                    else:
                        m = re.match(r'^([\w.]+(?:\[.*?\])?)\s*=\s*(.*)', s)
                        if m:
                            block['children'].append({'type': 'attr', 'key': m.group(1), 'value': m.group(2).rstrip()})
                        else:
                            block['children'].append({'type': 'raw', 'text': s})
                    if depth > 0:
                        i += 1
            else:
                m = re.match(r'^([\w.]+(?:\[.*?\])?)\s*=\s*(.*)', stripped)
                if m:
                    nodes.append({'type': 'attr', 'key': m.group(1), 'value': m.group(2).rstrip()})
                else:
                    nodes.append({'type': 'raw', 'text': stripped})
                i += 1

        return nodes

    def _normalize_header(self, header):
        """Normalize block header spacing."""
        # Split on whitespace but keep quoted strings intact
        parts = []
        i = 0
        h = header.strip()
        buf = ''
        while i < len(h):
            c = h[i]
            if c == '"':
                if buf.strip():
                    parts.extend(buf.split())
                    buf = ''
                j = i + 1
                while j < len(h):
                    if h[j] == '\\':
                        j += 2
                    elif h[j] == '"':
                        break
                    else:
                        j += 1
                parts.append('"' + h[i+1:j] + '"')
                i = j + 1
            else:
                buf += c
                i += 1
        if buf.strip():
            parts.extend(buf.split())
        return ' '.join(parts)

    def _format_tokens(self, nodes, indent):
        """Format nodes with proper indentation and alignment."""
        prefix = '  ' * indent
        result_lines = []
        i = 0

        while i < len(nodes):
            node = nodes[i]
            t = node['type']

            if t == 'blank':
                result_lines.append('')
                i += 1
            elif t == 'comment':
                result_lines.append(prefix + node['text'])
                i += 1
            elif t == 'raw':
                result_lines.append(prefix + node['text'])
                i += 1
            elif t == 'close':
                i += 1
            elif t == 'block':
                result_lines.append(prefix + node['header'] + ' {')
                inner = self._format_tokens(node['children'], indent + 1)
                if inner:
                    result_lines.append(inner)
                result_lines.append(prefix + '}')
                i += 1
            elif t == 'attr':
                # Collect group of attrs (separated by blank lines or blocks)
                group = []
                j = i
                while j < len(nodes):
                    n = nodes[j]
                    if n['type'] == 'attr':
                        group.append(n)
                        j += 1
                    elif n['type'] == 'comment':
                        group.append(n)
                        j += 1
                    elif n['type'] == 'blank':
                        break
                    else:
                        break

                # Find max key length in attr group
                attrs = [n for n in group if n['type'] == 'attr']
                max_klen = max((len(n['key']) for n in attrs), default=0)

                for gn in group:
                    if gn['type'] == 'attr':
                        pad = ' ' * (max_klen - len(gn['key']))
                        result_lines.append(f"{prefix}{gn['key']}{pad} = {gn['value']}")
                    elif gn['type'] == 'comment':
                        result_lines.append(prefix + gn['text'])

                i = j
            else:
                i += 1

        return '\n'.join(result_lines)
