            while j < n - 1:
                if content[j] == '*' and content[j+1] == '/':
                    j += 2
                    break
                if content[j] == '\n':
                    line += 1
                j += 1
            tokens.append(Token(Token.COMMENT, content[i:j], line))
            i = j

        # String
        elif c == '"':
            j = i + 1
            while j < n:
                if content[j] == '\\':
                    j += 2
                elif content[j] == '"':
