"""SQLite schema inspection and management."""
import sqlite3
import re
import os
import json


# Type mappings for SQLite types to Atlas HCL types
TYPE_MAPPINGS = {
    'integer': 'integer',
    'int': 'integer',
    'int2': 'int2', 
    'int4': 'integer',
    'int8': 'int8',
    'bigint': 'bigint',
    'smallint': 'smallint',
    'tinyint': 'tinyint',
    'mediumint': 'mediumint',
    'real': 'real',
    'float': 'float',
    'double': 'double',
    'text': 'text',
    'blob': 'blob',
    'numeric': 'numeric',
    'boolean': 'boolean',
    'bool': 'boolean',
    'date': 'date',
    'datetime': 'datetime',
    'clob': 'clob',
    'nvarchar': 'nvarchar',
    'varchar': 'varchar',
    'unsigned_big_int': 'unsigned_big_int',
    'nchar': 'nchar',
}

# Types that use sql() wrapper
SQL_WRAPPER_TYPES = {'time', 'timestamp', 'char'}


def parse_type(type_str):
    """Parse a SQLite type string and return Atlas HCL type representation."""
    if not type_str:
        return 'blob'

    type_lower = type_str.strip().lower()

    # Check for parameterized types
    m = re.match(r'^(nvarchar|varchar|nchar)\s*\((\d+)\)$', type_lower)
    if m:
        type_name = m.group(1)
        size = m.group(2)
        return f'{type_name}({size})'

    # Check for "unsigned big int" 
    if re.search(r'unsigned.*big.*int|unsigned.*int', type_lower):
        return 'unsigned_big_int'

    # Check for types that become sql() wrappers (char - but NOT nchar or varchar)
    base_type_m = re.match(r'^(\w+)', type_lower)
    if base_type_m:
        base = base_type_m.group(1)
        if base in SQL_WRAPPER_TYPES:
            return f'sql("{base}")'

    # Direct mappings
    simple_type = re.match(r'^(\w+)', type_lower)
    if simple_type:
        base = simple_type.group(1)
        if base in TYPE_MAPPINGS:
            return TYPE_MAPPINGS[base]

    # Fall back to sql() wrapper for unknown types
    return f'sql("{type_str}")'


