        if pk:
            pk_columns.append((pk, col_name))

        # Handle default values
        if default_val is not None:
            column['default'] = format_default(default_val, col_type)

        info['columns'].append(column)

    # Check for auto_increment
    if table_sql and 'AUTOINCREMENT' in table_sql.upper():
        # Find the auto-increment column (must be INTEGER PRIMARY KEY)
        for col in info['columns']:
            col_name = col['name']
            if any(c[1] == col_name for c in pk_columns):
                col['auto_increment'] = True
                break

    # Primary key
    if pk_columns:
        pk_columns.sort(key=lambda x: x[0])
        info['primary_key'] = [c[1] for c in pk_columns]

    # Get indexes
    indexes = conn.execute(f"PRAGMA index_list(\"{table_name}\")").fetchall()
    # (seq, name, unique, origin, partial)

    for idx in indexes:
        seq, idx_name, unique, origin, partial = idx
        # Skip auto-created pk indexes  
        if origin == 'pk':
            continue

        idx_cols = conn.execute(f"PRAGMA index_info(\"{idx_name}\")").fetchall()
        # (seqno, cid, name)
        idx_cols.sort(key=lambda x: x[0])

        index = {
            'name': idx_name,
            'unique': bool(unique),
            'columns': [c[2] for c in idx_cols],
            'origin': origin,
        }
        info['indexes'].append(index)

    # Get foreign keys
    fks = conn.execute(f"PRAGMA foreign_key_list(\"{table_name}\")").fetchall()
    # (id, seq, table, from, to, on_update, on_delete, match)

    # Group by FK id
    fk_groups = {}
    for fk in fks:
        fk_id, seq, ref_table, from_col, to_col, on_update, on_delete, match = fk
        if fk_id not in fk_groups:
            fk_groups[fk_id] = {
                'id': fk_id,
                'ref_table': ref_table,
                'columns': [],
                'ref_columns': [],
                'on_update': on_update,
                'on_delete': on_delete,
            }
        # Insert in seq order
        while len(fk_groups[fk_id]['columns']) <= seq:
            fk_groups[fk_id]['columns'].append(None)
            fk_groups[fk_id]['ref_columns'].append(None)
        fk_groups[fk_id]['columns'][seq] = from_col
        fk_groups[fk_id]['ref_columns'][seq] = to_col

    for fk_id in sorted(fk_groups.keys()):
        fk = fk_groups[fk_id]
        info['foreign_keys'].append({
            'name': str(fk_id),
            'columns': [c for c in fk['columns'] if c is not None],
            'ref_table': fk['ref_table'],
            'ref_columns': [c for c in fk['ref_columns'] if c is not None],
            'on_update': fk['on_update'],
            'on_delete': fk['on_delete'],
        })

    return info


def format_default(val, col_type):
    """Format a default value for HCL output."""
    if val is None:
        return None

    val_str = str(val)

    # SQL expression (starts with ( and ends with ))
    if val_str.startswith('(') and val_str.endswith(')'):
        inner = val_str[1:-1]
        return f'sql("{inner}")'

    # NULL literal
    if val_str.upper() == 'NULL':
        return 'sql("NULL")'

    # Boolean
    if val_str.upper() == 'TRUE':
        return 'true'
    if val_str.upper() == 'FALSE':
        return 'false'

    # Number (integer)
    try:
        int(val_str)
        return val_str
    except ValueError:
        pass

    # Number (float) - display as int if no fractional part
    try:
        f = float(val_str)
        if f == int(f):
            return str(int(f))
        return val_str
    except ValueError:
        pass

    # String with single quotes from SQLite
    if val_str.startswith("'") and val_str.endswith("'"):
        inner = val_str[1:-1].replace("''", "'")
        return '"' + inner + '"'

    # Current timestamp and other SQL functions
    if val_str.upper() in ('CURRENT_TIMESTAMP', 'CURRENT_DATE', 'CURRENT_TIME'):
        return f'sql("{val_str}")'

    # Unknown - wrap in sql()
    return f'sql("{val_str}")'


def schema_to_hcl(schema_info):
    """Convert schema info to HCL string."""
    lines = []

    for table in schema_info['tables']:
        if lines:
            pass  # No extra newline between tables
        lines.extend(table_to_hcl_lines(table, schema_info['schema']))

    # Schema block at end
    lines.append(f'schema "{schema_info["schema"]}" {{')
    lines.append('}')

    return '\n'.join(lines) + '\n'


def table_to_hcl_lines(table, schema_name):
    """Convert table info to HCL lines."""
    lines = []
    lines.append(f'table "{table["name"]}" {{')
    lines.append(f'  schema = schema.{schema_name}')

    # Columns
    for col in table['columns']:
        lines.extend(column_to_hcl_lines(col))

    # Primary key
    if table['primary_key']:
        pk_cols = ', '.join(f'column.{c}' for c in table['primary_key'])
        lines.append('  primary_key {')
        lines.append(f'    columns = [{pk_cols}]')
        lines.append('  }')

    # Foreign keys
    for fk in table['foreign_keys']:
        lines.extend(fk_to_hcl_lines(fk))

    # Indexes
    for idx in table['indexes']:
        lines.extend(index_to_hcl_lines(idx))

    # WITHOUT ROWID
    if table.get('without_rowid'):
        lines.append('  without_rowid = true')

    lines.append('}')
    return lines


def column_to_hcl_lines(col):
    """Convert column info to HCL lines."""
    lines = []
    lines.append(f'  column "{col["name"]}" {{')

    attrs = []
    attrs.append(('null', 'true' if col['null'] else 'false'))
    attrs.append(('type', col['type']))

    if col.get('auto_increment'):
        attrs.append(('auto_increment', 'true'))

    if col.get('default') is not None:
        attrs.append(('default', col['default']))

    # Find max key length for alignment
    max_klen = max(len(a[0]) for a in attrs)

    for key, value in attrs:
        pad = ' ' * (max_klen - len(key))
        lines.append(f'    {key}{pad} = {value}')

    lines.append('  }')
    return lines


def fk_to_hcl_lines(fk):
    """Convert FK info to HCL lines."""
    lines = []
    lines.append(f'  foreign_key "{fk["name"]}" {{')

    cols = ', '.join(f'column.{c}' for c in fk['columns'])
    ref_cols = ', '.join(f'table.{fk["ref_table"]}.column.{c}' for c in fk['ref_columns'])
    on_update = fk['on_update'].replace(' ', '_').upper()
    on_delete = fk['on_delete'].replace(' ', '_').upper()

    attrs = [
        ('columns', f'[{cols}]'),
        ('ref_columns', f'[{ref_cols}]'),
        ('on_update', on_update),
        ('on_delete', on_delete),
    ]

    max_klen = max(len(a[0]) for a in attrs)
    for key, value in attrs:
        pad = ' ' * (max_klen - len(key))
        lines.append(f'    {key}{pad} = {value}')

    lines.append('  }')
    return lines


def index_to_hcl_lines(idx):
    """Convert index info to HCL lines."""
    lines = []
    lines.append(f'  index "{idx["name"]}" {{')

    attrs = []
    if idx['unique']:
        attrs.append(('unique', 'true'))

    cols = ', '.join(f'column.{c}' for c in idx['columns'])
    attrs.append(('columns', f'[{cols}]'))

    if attrs:
        max_klen = max(len(a[0]) for a in attrs)
        for key, value in attrs:
            pad = ' ' * (max_klen - len(key))
            lines.append(f'    {key}{pad} = {value}')

    lines.append('  }')
    return lines


def schema_to_json(schema_info):
    """Convert schema info to JSON format."""
    result = {
        'schemas': [
            {
                'name': schema_info['schema'],
                'tables': []
            }
        ]
    }

    for table in schema_info['tables']:
        t = {
            'name': table['name'],
            'columns': [],
        }

        for col in table['columns']:
            c = {
                'name': col['name'],
                'type': hcl_type_to_json_type(col['type']),
            }
            if col['null']:
                c['null'] = True
            t['columns'].append(c)

        if table.get('indexes'):
            t['indexes'] = []
            for idx in table['indexes']:
                i = {
                    'name': idx['name'],
                    'parts': [{'column': c} for c in idx['columns']]
                }
                if idx['unique']:
                    i['unique'] = True
                t['indexes'].append(i)

        if table.get('primary_key'):
            t['primary_key'] = {
                'parts': [{'column': c} for c in table['primary_key']]
            }

        if table.get('foreign_keys'):
            t['foreign_keys'] = []
            for fk in table['foreign_keys']:
                f = {
                    'name': fk['name'],
                    'columns': fk['columns'],
                    'references': {
                        'table': fk['ref_table'],
                        'columns': fk['ref_columns']
                    }
                }
                t['foreign_keys'].append(f)

        result['schemas'][0]['tables'].append(t)

    return json.dumps(result, separators=(',', ':'))


def hcl_type_to_json_type(hcl_type):
    """Convert HCL type to JSON type string."""
    import re
    m = re.match(r'^sql\("(.+)"\)$', hcl_type)
    if m:
        return m.group(1).upper()

    m = re.match(r'^(\w+)\((\d+)\)$', hcl_type)
    if m:
        return f'{m.group(1).upper()}({m.group(2)})'

    return hcl_type.upper()


def schema_to_sql(schema_info):
    """Convert schema info to SQL DDL."""
    from sqlite_diff import generate_create_table_sql, generate_create_index_sql

    lines = []

    for table in schema_info['tables']:
        lines.append(f'-- Create "{table["name"]}" table')
        sql = generate_create_table_sql(table, multiline=False)
        lines.append(sql)

        for idx in table.get('indexes', []):
            unique_str = 'UNIQUE ' if idx.get('unique') else ''
            idx_name = idx['name']
            cols = ', '.join(f'`{c}`' for c in idx['columns'])
            unique_word = 'UNIQUE ' if idx.get('unique') else ''
            lines.append(f'-- Create index "{idx_name}" to table: "{table["name"]}"')
            lines.append(f'CREATE {unique_word}INDEX `{idx_name}` ON `{table["name"]}` ({cols});')

    return '\n'.join(lines)


def schema_to_mermaid(schema_info):
    """Convert schema info to Mermaid ERD format."""
    lines = ['erDiagram']

    for table in schema_info['tables']:
        lines.append(f'    {table["name"]} {{')
        for col in table['columns']:
            # Get base type name for mermaid
            type_str = mermaid_type(col['type'])

            attrs = []
            if table.get('primary_key') and col['name'] in table.get('primary_key', []):
                attrs.append('PK')

            # Check if FK column
            is_fk = any(
                col['name'] in fk['columns'] 
                for fk in table.get('foreign_keys', [])
            )
            if is_fk:
                attrs.append('FK')

            attr_str = ' '.join(attrs)
            if attr_str:
                lines.append(f'      {type_str} {col["name"]} {attr_str}')
            else:
                lines.append(f'      {type_str} {col["name"]}')
        lines.append('    }')

    # Relationships
    for table in schema_info['tables']:
        for fk in table.get('foreign_keys', []):
            from_table = table['name']
            to_table = fk['ref_table']
            fk_name = fk['name']
            lines.append(f'    {from_table} }}o--o| {to_table} : {fk_name}')

    return '\n'.join(lines)


def mermaid_type(hcl_type):
    """Get mermaid type from HCL type."""
    import re
    m = re.match(r'^sql\("(.+)"\)$', hcl_type)
    if m:
        return m.group(1).lower()

    m = re.match(r'^(\w+)\((\d+)\)$', hcl_type)
    if m:
        return m.group(1).lower()

    return hcl_type.lower()
