"""HCL configuration file parser for atlas.hcl project files."""
import os
import re
from hcl_fmt import tokenize_hcl, HCLParser


def load_config(config_url, env_name=None, vars=None):
    """
    Load an atlas.hcl config file and return the env configuration.

    config_url: file://path/to/atlas.hcl
    env_name: name of the environment to load
    vars: dict of variable overrides

    Returns: dict with 'url', 'dev', 'schemas', etc.
    """
    if not config_url:
        return None

    # Parse the URL
    if config_url.startswith('file://'):
        path = config_url[7:]
    else:
        path = config_url

    # Make path absolute if relative
    if not os.path.isabs(path):
        path = os.path.join(os.getcwd(), path)

    if not os.path.exists(path):
        return None

    with open(path, 'r') as f:
        content = f.read()

    # Parse the HCL
    config = parse_atlas_config(content, vars or {})

    if env_name is None:
        return config

    # Get specific env
    envs = config.get('env', {})
    if env_name not in envs:
        raise ValueError(f'env "{env_name}" not defined in config file')

    return envs[env_name]


def parse_atlas_config(content, vars=None):
    """Parse an atlas.hcl config file."""
    vars = vars or {}

    # Use HCL parser
    tokens = tokenize_hcl(content)
    parser = HCLParser(tokens)
    items = parser.parse_file()

    config = {
        'env': {},
        'variable': {},
        'locals': {},
    }

    # First pass: collect variables and locals
    for item in items:
        if item.get('type') == 'block':
            labels = item.get('labels', [])

            if labels and labels[0] == 'variable' and len(labels) >= 2:
                var_name = labels[1].strip('"')
                var_info = parse_var_block(item.get('children', []))

                # Apply override if provided
                if var_name in vars:
                    var_info['value'] = vars[var_name]
                elif 'default' in var_info:
                    var_info['value'] = var_info['default']

                config['variable'][var_name] = var_info

            elif labels and labels[0] == 'locals':
